	private List<Value> drainOwnedFinalInput(NativeRowsStep step, boolean ordered) throws Exception {
		NativeLmdbQuerySource evaluated = step.evaluationSource(EmptyBindingSet.getInstance());
		assertThat(evaluated).isInstanceOf(SyntheticValueSource.class);
			assertThat(SyntheticValueSource.inheritedEvaluation(evaluated)).isFalse();
		try (NativeExecutionContext owner = ((SyntheticValueSource) evaluated).executionContext()) {
			NativeRowsStep.initializeQueryBase(evaluated, EmptyBindingSet.getInstance());
			RowState row = new RowState(evaluated, step.layout, EmptyBindingSet.getInstance(), step.originalExpr);
			assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, evaluated, step.layout)).isTrue();
			SlotPlan consumer = new SlotPlan() {
				@Override
				public RowCursor open(RowState input) throws IOException {
					LmdbNativeInteriorPlans.Selection selected = LmdbNativeInteriorPlans.select(
							step.arg, input, step.consumerRequest);
					return selected.open(input, selected.plan);
				}

				@Override
				public long producedMask() {
					return step.arg.producedMask();
				}
			};
			List<Value> values = new ArrayList<>();
			int slot = step.layout.slot("n");
			try (RowCursor cursor = ordered ? LmdbNativeFactorAlgebra.openOrdered(consumer, row) : consumer.open(row)) {
				while (cursor.next()) {
					values.add(LmdbNativeValueCodec.toValue(row.decodedValue(slot, evaluated.nativeValueCodec(), false)));
				}
			}
			assertThat(row.encounterOrderRequired).isFalse();
			return values;
		}
	}

	@Test
	void finalResultKeepsVolatileNativeScopePinnedAndFreshForEachEvaluation() {
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			SailDatasetTripleTermSource source = source(dataset);
			LmdbNativeEvaluationStrategy strategy = strategy(source);
			assertOrderedValues(source, strategy);
			String query = "SELECT ?a ?b ?n ?u WHERE { <" + EX + "anchor> <" + EX + "a> ?a . "
					+ "{ SELECT (UUID() AS ?u) WHERE { } } ?b <" + EX + "b> ?n }";
			List<BindingSet> generic = drain(strategy.genericOnlyView().precompile(orderedRoot(query, source)));
			TupleExpr root = orderedRoot(query, source);
			QueryEvaluationStep prepared = strategy.precompileFinalTupleResult(QueryEvaluationUtility.pinFunctions(root));
			List<BindingSet> first = drain(prepared);
			List<BindingSet> second = drain(prepared);
			List<BindingSet> expected = baseRows(hand().subList(0, VALUES.length));
			assertThat(baseRows(generic)).containsExactlyInAnyOrderElementsOf(expected);
			for (List<BindingSet> result : List.of(first, second)) {
				assertThat(result).hasSize(3);
				assertThat(baseRows(result)).containsExactlyInAnyOrderElementsOf(expected);
				assertThat(result).allSatisfy(row -> assertThat(row.getBindingNames())
						.isEqualTo(Set.of("a", "b", "n", "u")));
				assertThat(result.stream().map(row -> row.getValue("u")).distinct().toList()).hasSize(1);
				assertThat(result.get(0).getValue("u")).isInstanceOf(IRI.class);
			}
			assertThat(first.get(0).getValue("u")).isNotEqualTo(second.get(0).getValue("u"));
			assertThat(root.getLongMetricActual("nativeInvocationsActual")).isPositive();
			assertThat(root.getLongMetricActual(OPTIMIZED)).isLessThanOrEqualTo(0L);
		}
	}

